-- Child lesson v3 content: picture books, NZ alternatives, games, colouring.
UPDATE public.curriculum_weeks SET kids_picture_book = 'The Quiet Book', kids_picture_book_author = 'Deborah Underwood', kids_picture_book_question = 'What kind of quiet do you like best?', kids_picture_book_note = 'There are many different kinds of quiet, and you have to stop to notice them.', kids_nz_alternative = 'Titiro Look', kids_nz_alternative_author = 'Gavin Bishop (Tainui, Ngāti Awa)', kids_nz_alternative_note = 'Looking closely at what is already in front of you.', kids_nz_alternative_verified = false, kids_read_aloud_source_check = '', kids_source = 'https://www.youtube.com/watch?v=UOsxlVpQT14', kids_game = 'Signal in the Static — Everyone hums, chatters and shuffles — that''s the noise. One child hides a beeping timer or shaker somewhere in the hall. The room has to go quiet enough, in stages, to hear it and find it. Repeat with the noise starting louder each time. WHY IT FITS: You cannot hear the quiet thing until you stop making noise.', kids_game_equipment = 'Kitchen timer or a shaker; something to hide it under', kids_game_under5 = 'Under-5s are the noise-makers and the finders. Hide it in plain sight and let them ''find'' it. Skip the staged quiet — just loud, then whisper, then silent.', kids_colouring_prompt = '' WHERE week_number = 1;
UPDATE public.curriculum_weeks SET kids_picture_book = 'Chrysanthemum', kids_picture_book_author = 'Kevin Henkes', kids_picture_book_question = 'Has anyone ever said something about you that wasn''t true?', kids_picture_book_note = 'What people say about you can start to feel true, even when it isn''t.', kids_nz_alternative = '', kids_nz_alternative_author = '', kids_nz_alternative_note = '', kids_nz_alternative_verified = false, kids_read_aloud_source_check = '', kids_source = '', kids_game = 'Label Tag — Each child wears a sticky label on their back with a made-up word (Sparkly, Slow, Loud, Bossy). Others treat them as that label for two minutes. Then everyone guesses their own label, peels it off and says one true thing about themselves instead. WHY IT FITS: Being told what you are, and choosing to take it off.', kids_game_equipment = 'Sticky labels, marker', kids_game_under5 = 'Give under-5s only kind or silly labels (Bouncy, Giggly). Keep it to 30 seconds and help them peel it off.', kids_colouring_prompt = '' WHERE week_number = 2;
UPDATE public.curriculum_weeks SET kids_picture_book = 'When Sophie Gets Angry — Really, Really Angry', kids_picture_book_author = 'Molly Bang', kids_picture_book_question = 'What helps you when you feel like Sophie?', kids_picture_book_note = 'The gap between feeling furious and doing something about it — Sophie goes outside instead.', kids_nz_alternative = 'Finding My Calm', kids_nz_alternative_author = 'Rebekah Lipp & Craig Phillips', kids_nz_alternative_note = 'Practical ways to find the pause before reacting.', kids_nz_alternative_verified = false, kids_read_aloud_source_check = '', kids_source = '', kids_game = 'Freeze in the Gap — Music plays and everyone moves. When it stops, freeze — but before you freeze you must take one big breath. Facilitator calls a feeling (''cross!'', ''excited!'') and children move like that, then freeze and breathe again. WHY IT FITS: The breath is the gap between the feeling and what you do.', kids_game_equipment = 'Speaker', kids_game_under5 = 'Under-5s just do stop-and-go with a big breath. Drop the feelings round or use only two: happy and sleepy.', kids_colouring_prompt = '' WHERE week_number = 3;
UPDATE public.curriculum_weeks SET kids_picture_book = 'Listening to My Body', kids_picture_book_author = 'Gabi Garcia', kids_picture_book_question = 'Where do you feel it in your body when you''re excited?', kids_picture_book_note = 'Sensations come before words. Your body tells you things first.', kids_nz_alternative = 'Let It Go: Emotions Are Energy in Motion', kids_nz_alternative_author = 'Rebekah Lipp & Craig Phillips', kids_nz_alternative_note = 'What sadness, anger, shame and fear actually feel like in the body.', kids_nz_alternative_verified = false, kids_read_aloud_source_check = '', kids_source = '', kids_game = 'Body Weather Report — Children move around. Facilitator calls a scenario (''you''re about to do a speech'', ''you''re getting a present''). Everyone freezes and puts a hand where they feel it — tummy, chest, head, hands. Then a quick show of hands: who felt it in the tummy? WHY IT FITS: The body answers before the words do.', kids_game_equipment = 'None', kids_game_under5 = 'Use only physical scenarios for under-5s — running fast, being tickled, being cold. Ask them to point to where it feels wobbly.', kids_colouring_prompt = '' WHERE week_number = 4;
UPDATE public.curriculum_weeks SET kids_picture_book = 'I Like Myself!', kids_picture_book_author = 'Karen Beaumont', kids_picture_book_question = 'What''s something you like about yourself?', kids_picture_book_note = 'Liking yourself on the inside, whatever the outside is doing.', kids_nz_alternative = '', kids_nz_alternative_author = '', kids_nz_alternative_note = '', kids_nz_alternative_verified = false, kids_read_aloud_source_check = '', kids_source = '', kids_game = 'Kind Mirror — Pairs face each other. One moves slowly, the other mirrors. Swap. Then each says one true, kind thing they noticed about their partner — how they moved, how carefully they copied. WHY IT FITS: Seeing someone properly, and saying it out loud.', kids_game_equipment = 'None', kids_game_under5 = 'Adult partners a under-5 and mirrors them, not the other way round. Big slow movements only.', kids_colouring_prompt = '' WHERE week_number = 5;
UPDATE public.curriculum_weeks SET kids_picture_book = 'Giraffes Can''t Dance', kids_picture_book_author = 'Giles Andreae', kids_picture_book_question = 'What are you good at that''s different from your friends?', kids_picture_book_note = 'Gerald compares himself to everyone else until he finds his own music.', kids_nz_alternative = '', kids_nz_alternative_author = '', kids_nz_alternative_note = '', kids_nz_alternative_verified = false, kids_read_aloud_source_check = '', kids_source = '', kids_game = 'The Same Cup — Each child gets an identical cup with a different amount of water. They compare, complain, negotiate — then discover that pouring into one big jug fills it exactly the same either way. WHY IT FITS: Comparing amounts stops mattering when you see the whole.', kids_game_equipment = 'Plastic cups, a large jug, water, towel', kids_game_under5 = 'Under-5s just pour, which they will love. Do it on a mat and expect spills. Skip the discussion.', kids_colouring_prompt = '' WHERE week_number = 6;
UPDATE public.curriculum_weeks SET kids_picture_book = 'The Bad Seed', kids_picture_book_author = 'Jory John', kids_picture_book_question = 'What does the unkind voice in your head say?', kids_picture_book_note = 'A seed who believes he''s bad because he''s been told so — and starts to change the story.', kids_nz_alternative = '', kids_nz_alternative_author = '', kids_nz_alternative_note = '', kids_nz_alternative_verified = false, kids_read_aloud_source_check = '', kids_source = '', kids_game = 'Boo Ball / Cheer Ball — Two soft balls. The ''boo ball'' is passed while the room says something grumpy and unhelpful (''you''ll never do it''). The ''cheer ball'' is passed with something honest and kind. Pass them at the same time and notice which one people want. WHY IT FITS: The mean voice and the kind one are both just voices.', kids_game_equipment = 'Two soft balls', kids_game_under5 = 'Under-5s hold only the cheer ball and pass it with a cheer. Do not give them the boo ball at all.', kids_colouring_prompt = '' WHERE week_number = 7;
UPDATE public.curriculum_weeks SET kids_picture_book = 'The Colour Monster', kids_picture_book_author = 'Anna Llenas', kids_picture_book_question = 'What colour is your feeling today?', kids_picture_book_note = 'Sorting the tangle — big feelings have names and each one is different.', kids_nz_alternative = 'How Do I Feel? A Dictionary of Emotions for Children', kids_nz_alternative_author = 'Rebekah Lipp, ill. Craig Phillips', kids_nz_alternative_note = '60+ emotions named, with what each one might be telling you. Storylines Notable winner.', kids_nz_alternative_verified = false, kids_read_aloud_source_check = '', kids_source = '', kids_game = 'Iceberg Hunt — Big feelings are written on cones at one end (ANGRY, GRUMPY, SHOUTY). Underneath each, hidden in a beanbag pile, are the small feelings (worried, left out, tired, hungry). Teams race to find what''s underneath their big feeling. WHY IT FITS: The big feeling is sitting on a smaller one.', kids_game_equipment = 'Cones, beanbags, cards', kids_game_under5 = 'Under-5s sort two piles: big feeling face, little feeling face. Use printed faces, not words.', kids_colouring_prompt = '' WHERE week_number = 8;
UPDATE public.curriculum_weeks SET kids_picture_book = 'The Rabbit Listened', kids_picture_book_author = 'Cori Doerrfeld', kids_picture_book_question = 'Who do you go to when something hurts?', kids_picture_book_note = 'Everyone tries to fix Taylor. The rabbit just sits with him. That''s what helps.', kids_nz_alternative = '', kids_nz_alternative_author = '', kids_nz_alternative_note = '', kids_nz_alternative_verified = false, kids_read_aloud_source_check = '', kids_source = '', kids_game = 'Safe Hands Relay — Children carry something fragile — an egg, a full cup, a tower of blocks — across the hall and hand it to a named safe grown-up at the other end. The point of the game is the handover, not the speed. WHY IT FITS: When something is hard to carry, you hand it to a safe grown-up.', kids_game_equipment = 'Plastic eggs or blocks, cups', kids_game_under5 = 'Under-5s carry a soft toy with two hands and hand it over. Shorten the distance to five metres. Always end with the handover.', kids_colouring_prompt = '' WHERE week_number = 9;
UPDATE public.curriculum_weeks SET kids_picture_book = 'Perfectly Norman', kids_picture_book_author = 'Tom Percival', kids_picture_book_question = 'What do you hide so people don''t see it?', kids_picture_book_note = 'Norman hides his wings under a coat so nobody sees. The coat gets heavy.', kids_nz_alternative = '', kids_nz_alternative_author = '', kids_nz_alternative_note = '', kids_nz_alternative_verified = false, kids_read_aloud_source_check = '', kids_source = '', kids_game = 'Mask Off — Each child holds a paper plate with a big smile drawn on it in front of their face and answers ''how are you?'' from behind it. Then they lower it and answer again. No one has to say anything different — but they can. WHY IT FITS: Sometimes the face and the feeling are not the same.', kids_game_equipment = 'Paper plates, markers, sticks', kids_game_under5 = 'Under-5s just play peekaboo with the plate. Ask ''happy face or sad face?'' and let them show you.', kids_colouring_prompt = '' WHERE week_number = 10;
UPDATE public.curriculum_weeks SET kids_picture_book = 'The Invisible Boy', kids_picture_book_author = 'Trudy Ludwig', kids_picture_book_question = 'Who in your class might be feeling invisible?', kids_picture_book_note = 'Brian is unseen until one person notices him.', kids_nz_alternative = 'Colour the Stars', kids_nz_alternative_author = 'Dawn McMillan', kids_nz_alternative_note = 'A friendship that requires seeing the world through someone else''s experience.', kids_nz_alternative_verified = false, kids_read_aloud_source_check = '', kids_source = '', kids_game = 'The Backpack Game — Volunteers wear a backpack loaded with soft objects, each one labelled with something invisible (''didn''t sleep'', ''lost my lunch'', ''moved house''). They try to do a simple task — hop, catch, skip. The room guesses what might be in the bag. WHY IT FITS: Everyone is carrying something you cannot see.', kids_game_equipment = 'Backpack, soft objects, labels', kids_game_under5 = 'Under-5s wear a nearly empty backpack and try to skip. Keep the load light and the task short.', kids_colouring_prompt = '' WHERE week_number = 11;
UPDATE public.curriculum_weeks SET kids_picture_book = 'Interrupting Chicken', kids_picture_book_author = 'David Ezra Stein', kids_picture_book_question = 'What do you always do without meaning to?', kids_picture_book_note = 'A chicken who interrupts without ever deciding to — and slowly notices she does it.', kids_nz_alternative = '', kids_nz_alternative_author = '', kids_nz_alternative_note = '', kids_nz_alternative_verified = false, kids_read_aloud_source_check = '', kids_source = '', kids_game = 'Loop Track — Chalk or tape a loop on the floor with three stations: TRIGGER, WHAT I DO, WHAT I GET. Children walk their own loop for a habit (bored → tablet → fun) and then try walking a different second station. WHY IT FITS: A habit is a track you walk without choosing.', kids_game_equipment = 'Floor tape or chalk, station signs', kids_game_under5 = 'Under-5s just walk the loop holding an adult''s hand and stamp at each station. Name the stations aloud for them.', kids_colouring_prompt = '' WHERE week_number = 12;
UPDATE public.curriculum_weeks SET kids_picture_book = 'The Wonderful Things You Will Be', kids_picture_book_author = 'Emily Winfield Martin', kids_picture_book_question = 'What have you found out about yourself this term?', kids_picture_book_note = 'Looking back and looking forward, without needing to know the ending.', kids_nz_alternative = '', kids_nz_alternative_author = '', kids_nz_alternative_note = '', kids_nz_alternative_verified = false, kids_read_aloud_source_check = '', kids_source = '', kids_game = 'Treasure Map Review — Thirteen stations around the hall, one per week, each with a picture from that session. Children move around collecting a stamp and saying one thing they remember. Ends with the whole map on the wall. WHY IT FITS: Looking back at everything we noticed.', kids_game_equipment = 'Station cards, stamps or stickers, wall map', kids_game_under5 = 'Under-5s collect stickers with a buddy. Six stations, not thirteen.', kids_colouring_prompt = '' WHERE week_number = 13;
UPDATE public.curriculum_weeks SET kids_picture_book = 'What Do You Do With an Idea?', kids_picture_book_author = 'Kobi Yamada', kids_picture_book_question = 'What''s your idea that you haven''t told anyone?', kids_picture_book_note = 'Nobody gives you permission for your idea. You decide to look after it.', kids_nz_alternative = '', kids_nz_alternative_author = '', kids_nz_alternative_note = '', kids_nz_alternative_verified = false, kids_read_aloud_source_check = '', kids_source = '', kids_game = 'Red Light, Own Light — Standard red light / green light, but after three rounds the facilitator stops calling. Children have to decide themselves when to move. Some freeze waiting. Talk about waiting for permission that isn''t coming. WHY IT FITS: Nobody is coming to say go.', kids_game_equipment = 'None', kids_game_under5 = 'Under-5s play normal red light green light. Do the no-caller round for ten seconds only, with an adult modelling moving.', kids_colouring_prompt = '' WHERE week_number = 14;
UPDATE public.curriculum_weeks SET kids_picture_book = 'Red: A Crayon''s Story', kids_picture_book_author = 'Michael Hall', kids_picture_book_question = 'Has anyone ever expected you to be something you''re not?', kids_picture_book_note = 'A crayon labelled red who is actually blue. Everyone tries to fix him.', kids_nz_alternative = '', kids_nz_alternative_author = '', kids_nz_alternative_note = '', kids_nz_alternative_verified = false, kids_read_aloud_source_check = '', kids_source = '', kids_game = 'Costume Swap — A pile of dress-ups. Children are told to dress as what other people expect them to be, walk the hall, then swap into what they''d actually pick. Two laps, two feelings. WHY IT FITS: Wearing what''s expected, then choosing.', kids_game_equipment = 'Dress-up box, hats, scarves', kids_game_under5 = 'Under-5s just do the second lap — dress as whatever they like and parade. Skip the first lap entirely.', kids_colouring_prompt = '' WHERE week_number = 15;
UPDATE public.curriculum_weeks SET kids_picture_book = 'Enemy Pie', kids_picture_book_author = 'Derek Munson', kids_picture_book_question = 'Who are you cross with, and how long have you been cross?', kids_picture_book_note = 'Staying cross takes a lot of work. Spending a day together takes less.', kids_nz_alternative = '', kids_nz_alternative_author = '', kids_nz_alternative_note = '', kids_nz_alternative_verified = false, kids_read_aloud_source_check = '', kids_source = '', kids_game = 'Heavy Beanbags — Each grudge is a beanbag. Children name something they''re cross about (or make one up) and add a beanbag to their arms. Then they try to catch, hug or high-five while holding them all. They can put one down whenever they like. WHY IT FITS: Staying cross is heavy, and putting it down is your choice.', kids_game_equipment = 'Beanbags', kids_game_under5 = 'Under-5s hold two soft toys and try to clap. Let them drop them and cheer. No naming required.', kids_colouring_prompt = '' WHERE week_number = 16;
UPDATE public.curriculum_weeks SET kids_picture_book = 'The Girl Who Never Made Mistakes', kids_picture_book_author = 'Mark Pett & Gary Rubinstein', kids_picture_book_question = 'What happened last time you got something wrong?', kids_picture_book_note = 'Beatrice is terrified of getting it wrong — until she does, and the world doesn''t end.', kids_nz_alternative = '', kids_nz_alternative_author = '', kids_nz_alternative_note = '', kids_nz_alternative_verified = false, kids_read_aloud_source_check = '', kids_source = '', kids_game = 'Do-Over Station — Skittles or a bean-bag toss. Everyone misses on purpose first. Then everyone gets a do-over and a friendly line to say to themselves: ''that''s okay, go again.'' Nobody keeps score. WHY IT FITS: Getting it wrong, and being kind about it.', kids_game_equipment = 'Skittles or cones, beanbags', kids_game_under5 = 'Under-5s get unlimited do-overs and a big cheer for every throw. Move the line closer.', kids_colouring_prompt = '' WHERE week_number = 17;
UPDATE public.curriculum_weeks SET kids_picture_book = 'I Am Enough', kids_picture_book_author = 'Grace Byers', kids_picture_book_question = 'What would a kind coach say to you?', kids_picture_book_note = 'The kind, honest voice — what it sounds like when you''re on your own side.', kids_nz_alternative = '', kids_nz_alternative_author = '', kids_nz_alternative_note = '', kids_nz_alternative_verified = false, kids_read_aloud_source_check = '', kids_source = '', kids_game = 'Coach in Your Ear — One child does a simple challenge (balance on a line, bounce a ball ten times). One partner plays the mean voice quietly, one plays the honest kind coach. Swap. Which one helped? WHY IT FITS: You can choose which voice coaches you.', kids_game_equipment = 'Balls, floor tape', kids_game_under5 = 'For under-5s, only the coach role exists. An adult cheers them along a balance line. Never let a small child be the mean voice.', kids_colouring_prompt = '' WHERE week_number = 18;
UPDATE public.curriculum_weeks SET kids_picture_book = 'Don''t Hug Doug', kids_picture_book_author = 'Carrie Finison', kids_picture_book_question = 'When did you say yes when you wanted to say no?', kids_picture_book_note = 'Doug doesn''t like hugs, and that''s allowed. Ask first, and no is a real answer.', kids_nz_alternative = '', kids_nz_alternative_author = '', kids_nz_alternative_note = '', kids_nz_alternative_verified = false, kids_read_aloud_source_check = '', kids_source = '', kids_game = 'Yes/No Islands — Two hoops: YES and NO. Facilitator calls out things (''want to be first?'', ''want a hug from someone you don''t know?'', ''want to share your snack?''). Children jump to their honest answer. No one is allowed to comment on anyone else''s island. WHY IT FITS: Your answer is allowed to be no.', kids_game_equipment = 'Two hoops or floor tape', kids_game_under5 = 'Under-5s answer with thumbs up or down while sitting. Use only easy, safe questions.', kids_colouring_prompt = '' WHERE week_number = 19;
UPDATE public.curriculum_weeks SET kids_picture_book = 'Stone Soup', kids_picture_book_author = 'Jon J Muth', kids_picture_book_question = 'What could you bring that would help everyone?', kids_picture_book_note = 'Everyone thinks there isn''t enough, until everyone brings one thing.', kids_nz_alternative = '', kids_nz_alternative_author = '', kids_nz_alternative_note = '', kids_nz_alternative_verified = false, kids_read_aloud_source_check = '', kids_source = '', kids_game = 'The Never-Ending Cheer — One child is cheered by the room. Then two. Then everyone at once. The room notices that the cheering did not run out — unlike a bag of sweets, which is passed around alongside it and does. WHY IT FITS: Some things run out. Kindness doesn''t.', kids_game_equipment = 'A small bag of something shareable', kids_game_under5 = 'Under-5s get cheered first and loudest. Keep it to one round each.', kids_colouring_prompt = '' WHERE week_number = 20;
UPDATE public.curriculum_weeks SET kids_picture_book = 'Wilfrid Gordon McDonald Partridge', kids_picture_book_author = 'Mem Fox', kids_picture_book_question = 'What have the grown-ups who look after you taught you?', kids_picture_book_note = 'What we carry from the people who care for us, and what we give back.', kids_nz_alternative = '', kids_nz_alternative_author = '', kids_nz_alternative_note = '', kids_nz_alternative_verified = false, kids_read_aloud_source_check = '', kids_source = '', kids_game = 'Follow the Leader Chain — A leader starts a movement, the line copies. Every 30 seconds the leader goes to the back and a new one starts. At the end: which move did you keep doing even after that leader was gone? WHY IT FITS: We keep doing what the people ahead of us did.', kids_game_equipment = 'Speaker', kids_game_under5 = 'Under-5s go near the front where the movement is clearest. Give them a turn as leader and copy them enthusiastically.', kids_colouring_prompt = '' WHERE week_number = 21;
UPDATE public.curriculum_weeks SET kids_picture_book = 'Ruby Finds a Worry', kids_picture_book_author = 'Tom Percival', kids_picture_book_question = 'What do you keep to yourself that''s getting heavy?', kids_picture_book_note = 'Ruby''s worry grows because she keeps it to herself. It shrinks when she says it out loud.', kids_nz_alternative = 'Aroha''s Way', kids_nz_alternative_author = 'Rebekah Lipp & Craig Phillips', kids_nz_alternative_note = 'Worry, nervousness and apprehension — and tools to set them down.', kids_nz_alternative_verified = false, kids_read_aloud_source_check = '', kids_source = '', kids_game = 'Fortress — Children build a wall around themselves from soft blocks or cushions, then try to pass a ball to a friend through it. Then they take one block out. Then another. How much wall do you actually need? WHY IT FITS: Walls keep things out, including the good things.', kids_game_equipment = 'Soft blocks, cushions, soft ball', kids_game_under5 = 'Under-5s build a small wall and knock it down, which is the whole game for them. Cheer the knocking down.', kids_colouring_prompt = '' WHERE week_number = 22;
UPDATE public.curriculum_weeks SET kids_picture_book = 'The Memory Tree', kids_picture_book_author = 'Britta Teckentrup', kids_picture_book_question = 'What ended that you still think about?', kids_picture_book_note = 'Fox''s friends gather to remember him, and a tree grows from the remembering.', kids_nz_alternative = 'Finding Monkey Moon', kids_nz_alternative_author = 'Elizabeth Pulford, ill. Kate Wilkinson', kids_nz_alternative_note = 'Losing something loved, and the search for it.', kids_nz_alternative_verified = false, kids_read_aloud_source_check = '', kids_source = '', kids_game = 'Autumn Leaves — Everyone holds a paper leaf with something that ended written or drawn on it. On a signal they let them fall. Then the leaves are swept into a pile and seeds or paper flowers are planted in it. WHY IT FITS: When something ends it makes space.', kids_game_equipment = 'Paper leaves, markers, paper flowers', kids_game_under5 = 'Under-5s draw on their leaf and drop it. Let them do the sweeping — they will want to.', kids_colouring_prompt = '' WHERE week_number = 23;
UPDATE public.curriculum_weeks SET kids_picture_book = 'Jabari Jumps', kids_picture_book_author = 'Gaia Cornwall', kids_picture_book_question = 'What are you scared of that you''d like to try?', kids_picture_book_note = 'Jabari is scared of the diving board and jumps anyway. Fear is information, not an instruction.', kids_nz_alternative = 'Lucy and the Dark', kids_nz_alternative_author = 'Melinda Szymanik, ill. Vasanti Unka', kids_nz_alternative_note = 'Fear of the dark, met rather than avoided.', kids_nz_alternative_verified = false, kids_read_aloud_source_check = '', kids_source = '', kids_game = 'Burnt Toast Alarm — A loud alarm goes off at random. Children freeze, then check: is it a fire, or is it burnt toast? A card is revealed each time — most say burnt toast. They practise the check before reacting. WHY IT FITS: Not every alarm is an emergency.', kids_game_equipment = 'Bell or buzzer, picture cards', kids_game_under5 = 'Under-5s just freeze and do a big breath when the bell rings. Skip the cards; use a gentle bell, not a buzzer.', kids_colouring_prompt = '' WHERE week_number = 24;
UPDATE public.curriculum_weeks SET kids_picture_book = 'Not Quite Narwhal', kids_picture_book_author = 'Jessie Sima', kids_picture_book_question = 'What did you used to believe about yourself that isn''t true now?', kids_picture_book_note = 'Kelp has always been told what he is — and finds out the old story isn''t the whole one.', kids_nz_alternative = '', kids_nz_alternative_author = '', kids_nz_alternative_note = '', kids_nz_alternative_verified = false, kids_read_aloud_source_check = '', kids_source = '', kids_game = 'Old Coat — Children put on a coat several sizes too small (or a tiny hat) and try to move. It fitted once. Then they swap for one that fits now. WHY IT FITS: Some stories about you don''t fit any more.', kids_game_equipment = 'Assorted dress-up coats and hats, all sizes', kids_game_under5 = 'Under-5s find the hat that fits from a pile. Turn it into a hat parade.', kids_colouring_prompt = '' WHERE week_number = 25;
UPDATE public.curriculum_weeks SET kids_picture_book = 'The Heart and the Bottle', kids_picture_book_author = 'Oliver Jeffers', kids_picture_book_question = 'What have you put down this term?', kids_picture_book_note = 'A girl puts her heart in a bottle to keep it safe, and has to work out how to get it back.', kids_nz_alternative = '', kids_nz_alternative_author = '', kids_nz_alternative_note = '', kids_nz_alternative_verified = false, kids_read_aloud_source_check = '', kids_source = '', kids_game = 'Backpack Empty-Out — Children carry a heavy-ish backpack around a course. Then they name one thing to take out, remove a weight, and do the course again. And again. Notice the difference each time. WHY IT FITS: We have put things down this term.', kids_game_equipment = 'Backpacks, soft weights or cushions', kids_game_under5 = 'Under-5s carry one item, take it out, and run the short course. Two laps maximum.', kids_colouring_prompt = '' WHERE week_number = 26;
UPDATE public.curriculum_weeks SET kids_picture_book = 'Elmer', kids_picture_book_author = 'David McKee', kids_picture_book_question = 'Who do you want to be?', kids_picture_book_note = 'Elmer tries to be like the other elephants, and everything goes grey.', kids_nz_alternative = 'Paku Manu Ariki Whakatakapōkai', kids_nz_alternative_author = 'Michaela Keeble, ill. Tokerau Brown', kids_nz_alternative_note = 'A young Māori boy overflowing with questions about identity, culture and belonging.', kids_nz_alternative_verified = false, kids_read_aloud_source_check = '', kids_source = '', kids_game = 'Build-a-Me Statue — In pairs, one child sculpts the other into a statue of ''who I want to be'' — brave, calm, kind. Photograph nothing; just walk the gallery and guess. Then everyone strikes their own chosen pose at once. WHY IT FITS: You get to choose the shape you take.', kids_game_equipment = 'None', kids_game_under5 = 'Sculpting means posing themselves, not being moved by someone else. Under-5s copy an adult''s pose. No hands-on posing of any child, by anyone.', kids_colouring_prompt = '' WHERE week_number = 27;
UPDATE public.curriculum_weeks SET kids_picture_book = 'The Three Questions', kids_picture_book_author = 'Jon J Muth', kids_picture_book_question = 'What''s the most important thing to you?', kids_picture_book_note = 'What matters most, who matters most, and when is the right time.', kids_nz_alternative = '', kids_nz_alternative_author = '', kids_nz_alternative_note = '', kids_nz_alternative_verified = false, kids_read_aloud_source_check = '', kids_source = '', kids_game = 'Rescue the Treasures — Ten objects scattered in the hall, a rope ''river'' across the middle. Teams may only carry three across. They must decide together which three matter most, and say why. WHY IT FITS: When you can''t have everything, what do you choose?', kids_game_equipment = 'Assorted objects, rope', kids_game_under5 = 'Under-5s rescue one object each and say why they picked it. Skip the group decision.', kids_colouring_prompt = '' WHERE week_number = 28;
UPDATE public.curriculum_weeks SET kids_picture_book = 'The Most Magnificent Thing', kids_picture_book_author = 'Ashley Spires', kids_picture_book_question = 'What do you practise, even when it''s hard?', kids_picture_book_note = 'Making it again and again — the small repeated attempt is the whole thing.', kids_nz_alternative = '', kids_nz_alternative_author = '', kids_nz_alternative_note = '', kids_nz_alternative_verified = false, kids_read_aloud_source_check = '', kids_source = '', kids_game = 'One Brick at a Time — Every child adds one block to a shared tower each time they complete a small action — ten star jumps, one kind word, tying a lace. Fast building is not allowed. One brick, one action. WHY IT FITS: Small things done again and again build something.', kids_game_equipment = 'Building blocks or cups', kids_game_under5 = 'Under-5s add a block for every star jump. Big blocks, low tower, lots of cheering.', kids_colouring_prompt = '' WHERE week_number = 29;
UPDATE public.curriculum_weeks SET kids_picture_book = 'I Am Yoga', kids_picture_book_author = 'Susan Verde', kids_picture_book_question = 'What does your body need more of?', kids_picture_book_note = 'The body as the place you come back to when everything is too much.', kids_nz_alternative = 'Aroha Knows', kids_nz_alternative_author = 'Rebekah Lipp & Craig Phillips', kids_nz_alternative_note = 'The places and spaces that make us feel safe and well.', kids_nz_alternative_verified = false, kids_read_aloud_source_check = '', kids_source = '', kids_game = 'Foundation Wobble — Teams build the tallest tower they can on a wobbly base (a cushion). Then rebuild on a firm one. Same blocks, different base. WHY IT FITS: What you build sits on how you sleep, eat and move.', kids_game_equipment = 'Blocks, cushions, firm boards', kids_game_under5 = 'Under-5s build on the cushion and knock it over. Then build on the floor. Compare heights with them.', kids_colouring_prompt = '' WHERE week_number = 30;
UPDATE public.curriculum_weeks SET kids_picture_book = 'Stick and Stone', kids_picture_book_author = 'Beth Ferry', kids_picture_book_question = 'Who makes you feel most like yourself?', kids_picture_book_note = 'Who you become depends a lot on who''s standing next to you.', kids_nz_alternative = '', kids_nz_alternative_author = '', kids_nz_alternative_note = '', kids_nz_alternative_verified = false, kids_read_aloud_source_check = '', kids_source = '', kids_game = 'Garden Circle — Children plant themselves as ''seeds'' around the hall. Some spots are near the music and cheering, some near a grumpy corner. Everyone tries to grow (stretch up) in their spot. Then they choose a new one. WHY IT FITS: You grow differently depending on where you plant yourself.', kids_game_equipment = 'Speaker, cones', kids_game_under5 = 'Under-5s go straight to the cheering corner and grow. Skip the grumpy corner entirely for them.', kids_colouring_prompt = '' WHERE week_number = 31;
UPDATE public.curriculum_weeks SET kids_picture_book = 'I Can Do Hard Things', kids_picture_book_author = 'Gabi Garcia', kids_picture_book_question = 'What would you say to a friend who was where you are?', kids_picture_book_note = 'Self-talk you can actually hear yourself saying — not slogans, sentences.', kids_nz_alternative = '', kids_nz_alternative_author = '', kids_nz_alternative_note = '', kids_nz_alternative_verified = false, kids_read_aloud_source_check = '', kids_source = '', kids_game = 'Echo Hall — One child says something to the far wall; the room echoes it back. Say something harsh — the room echoes it harshly. Say something kind — same. The room only gives back what was sent. WHY IT FITS: What you say to yourself comes back.', kids_game_equipment = 'None', kids_game_under5 = 'Under-5s shout a happy word and hear it echoed. Only kind words for this age group.', kids_colouring_prompt = '' WHERE week_number = 32;
UPDATE public.curriculum_weeks SET kids_picture_book = 'The Very Hungry Caterpillar', kids_picture_book_author = 'Eric Carle', kids_picture_book_question = 'What part of your week do you look forward to?', kids_picture_book_note = 'Days with a rhythm, and what the rhythm builds toward.', kids_nz_alternative = '', kids_nz_alternative_author = '', kids_nz_alternative_note = '', kids_nz_alternative_verified = false, kids_read_aloud_source_check = '', kids_source = '', kids_game = 'Rhythm Course — An obstacle course is run in a random order first — chaotic, tiring. Then it''s run in a set rhythm with a drumbeat. Same course, different feeling. WHY IT FITS: A rhythm makes the same work easier.', kids_game_equipment = 'Cones, hoops, drum or speaker', kids_game_under5 = 'Under-5s only do the rhythm version, holding a partner''s hand. Four obstacles maximum.', kids_colouring_prompt = '' WHERE week_number = 33;
UPDATE public.curriculum_weeks SET kids_picture_book = 'I Am Peace', kids_picture_book_author = 'Susan Verde', kids_picture_book_question = 'When do you feel properly rested?', kids_picture_book_note = 'Rest and stillness as something you practise, not something you earn.', kids_nz_alternative = 'At the Bach', kids_nz_alternative_author = 'Joy Cowley, ill. Hilary Jean Tapper', kids_nz_alternative_note = 'Unhurried time, and what rest actually looks like.', kids_nz_alternative_verified = false, kids_read_aloud_source_check = '', kids_source = '', kids_game = 'The Rest Station — A relay where every third lap you must lie down on a mat for 30 seconds. Teams that skip the rest get slower. Teams that rest properly get faster. WHY IT FITS: Rest is part of the game, not a reward at the end.', kids_game_equipment = 'Mats or towels, cones', kids_game_under5 = 'Under-5s do the resting station only — lying down, being counted down from ten. They will treat it as the best part.', kids_colouring_prompt = '' WHERE week_number = 34;
UPDATE public.curriculum_weeks SET kids_picture_book = 'The Dot', kids_picture_book_author = 'Peter H. Reynolds', kids_picture_book_question = 'What do you love making?', kids_picture_book_note = 'Vashti makes one mark, and then keeps going because she wanted to.', kids_nz_alternative = 'Dazzlehands', kids_nz_alternative_author = 'Sacha Cotter, ill. Josh Morgan', kids_nz_alternative_note = 'Making things with your own two hands.', kids_nz_alternative_verified = false, kids_read_aloud_source_check = '', kids_source = '', kids_game = 'Junk Orchestra — A pile of random objects. In small groups, children have five minutes to make an instrument and a sound. Then a two-minute performance. Nobody is judged and there is no winner. WHY IT FITS: Making something because you want to.', kids_game_equipment = 'Containers, rice, elastic bands, boxes, spoons', kids_game_under5 = 'Under-5s shake a filled bottle. Make the bottles in advance and seal them properly.', kids_colouring_prompt = '' WHERE week_number = 35;
UPDATE public.curriculum_weeks SET kids_picture_book = 'Maybe', kids_picture_book_author = 'Kobi Yamada', kids_picture_book_question = 'What are you doing when you forget about time?', kids_picture_book_note = 'What you have, meeting what the world needs — without needing to know the plan.', kids_nz_alternative = '', kids_nz_alternative_author = '', kids_nz_alternative_note = '', kids_nz_alternative_verified = false, kids_read_aloud_source_check = '', kids_source = '', kids_game = 'The Missing Piece — Each child is given one puzzle piece or one job (holder, counter, cheerer, fetcher). The task can only be completed if everyone does their bit. Then one job is removed and they try again. WHY IT FITS: What you''re good at is needed by someone.', kids_game_equipment = 'Large floor puzzle or a group task', kids_game_under5 = 'Under-5s get the cheering job, which is real and visible. Make sure someone notices them doing it.', kids_colouring_prompt = '' WHERE week_number = 36;
UPDATE public.curriculum_weeks SET kids_picture_book = 'A Chair for My Mother', kids_picture_book_author = 'Vera B. Williams', kids_picture_book_question = 'What would you save up for?', kids_picture_book_note = 'Saving coins in a jar for something the whole family needs.', kids_nz_alternative = '', kids_nz_alternative_author = '', kids_nz_alternative_note = '', kids_nz_alternative_verified = false, kids_read_aloud_source_check = '', kids_source = '', kids_game = 'Ten Buttons — Every child gets ten buttons. Around the hall are stations: things you need (water, food), things you want (toy, treat), and a giving jar. They spend their ten and then talk about it. WHY IT FITS: Money is choices, and some of them are for other people.', kids_game_equipment = 'Buttons or counters, station cards, a jar', kids_game_under5 = 'Under-5s get three buttons and two stations: something for me, something for someone else. Watch for choking hazards — use large counters.', kids_colouring_prompt = '' WHERE week_number = 37;
UPDATE public.curriculum_weeks SET kids_picture_book = 'The Big Umbrella', kids_picture_book_author = 'Amy June Bates', kids_picture_book_question = 'What do you bring to a group?', kids_picture_book_note = 'The umbrella always stretches. There is always room for one more.', kids_nz_alternative = '', kids_nz_alternative_author = '', kids_nz_alternative_note = '', kids_nz_alternative_verified = false, kids_read_aloud_source_check = '', kids_source = '', kids_game = 'The Hive — The room has to move a pile of beanbags from one end to the other, but each child may only use one specific action (roll, pass, carry, throw, catch). Nobody can do the whole job alone. WHY IT FITS: We each bring one thing, and together it works.', kids_game_equipment = 'Beanbags, cones', kids_game_under5 = 'Under-5s get the carrying job with a partner. Shorten the distance.', kids_colouring_prompt = '' WHERE week_number = 38;
UPDATE public.curriculum_weeks SET kids_picture_book = 'Ish', kids_picture_book_author = 'Peter H. Reynolds', kids_picture_book_question = 'What''s different about you now?', kids_picture_book_note = 'Not finished, not perfect — becoming. Ramon draws vase-ish and it''s better.', kids_nz_alternative = '', kids_nz_alternative_author = '', kids_nz_alternative_note = '', kids_nz_alternative_verified = false, kids_read_aloud_source_check = '', kids_source = '', kids_game = 'Then and Now — Children re-run one game from earlier in the year — week 3''s freeze game works well — and notice what''s different about how they play it now. WHY IT FITS: You are not the same as you were.', kids_game_equipment = 'Whatever the chosen game needs', kids_game_under5 = 'Under-5s repeat week 3''s stop-and-go. Ask them if it feels easier.', kids_colouring_prompt = '' WHERE week_number = 39;
UPDATE public.curriculum_weeks SET kids_picture_book = 'Have You Filled a Bucket Today?', kids_picture_book_author = 'Carol McCloud', kids_picture_book_question = 'Who could you help this week?', kids_picture_book_note = 'What you''ve grown is for other people. Filling someone''s bucket fills yours.', kids_nz_alternative = '', kids_nz_alternative_author = '', kids_nz_alternative_note = '', kids_nz_alternative_verified = false, kids_read_aloud_source_check = '', kids_source = '', kids_game = 'Helping Hands Relay — A course that cannot be completed alone — one child is ''stuck'' at each station and must be helped past by the next runner. The runner who helps most is the point, not the fastest. WHY IT FITS: What you''ve learned is for other people too.', kids_game_equipment = 'Cones, hoops', kids_game_under5 = 'Under-5s are the ones helped, paired with an older buddy. Then swap so they get to help too.', kids_colouring_prompt = '' WHERE week_number = 40;
UPDATE public.curriculum_weeks SET kids_picture_book = 'Mango, Abuela, and Me', kids_picture_book_author = 'Meg Medina', kids_picture_book_question = 'What could you teach someone younger than you?', kids_picture_book_note = 'Two people teaching each other, both learning.', kids_nz_alternative = '', kids_nz_alternative_author = '', kids_nz_alternative_note = '', kids_nz_alternative_verified = false, kids_read_aloud_source_check = '', kids_source = '', kids_game = 'Teach Me That — Every child teaches one thing they can do — a clap pattern, a stretch, a knot, a joke — to two other people. Then those two teach it on. Count how far one skill travels around the hall. WHY IT FITS: You know it better once you''ve taught it.', kids_game_equipment = 'None', kids_game_under5 = 'Under-5s teach a clap or a silly face. Adults learn it from them with obvious enthusiasm.', kids_colouring_prompt = '' WHERE week_number = 41;
UPDATE public.curriculum_weeks SET kids_picture_book = 'Say Something!', kids_picture_book_author = 'Peter H. Reynolds', kids_picture_book_question = 'What''s true about you that you keep hidden?', kids_picture_book_note = 'Being seen and heard — in whatever way is yours.', kids_nz_alternative = '', kids_nz_alternative_author = '', kids_nz_alternative_note = '', kids_nz_alternative_verified = false, kids_read_aloud_source_check = '', kids_source = '', kids_game = 'Spotlight, One Step — A torch spotlight on the floor. Children step into it for as long as they want — one second is fine — and the room gives a warm cheer. Nobody has to speak. Nobody may be pushed in. WHY IT FITS: Being seen is nicer than it is scary.', kids_game_equipment = 'Torch or lamp', kids_game_under5 = 'Under-5s go in pairs holding hands. Cheer even harder. Never coax a child who says no.', kids_colouring_prompt = '' WHERE week_number = 42;
UPDATE public.curriculum_weeks SET kids_picture_book = 'One', kids_picture_book_author = 'Kathryn Otoshi', kids_picture_book_question = 'When is it hardest to do the right thing?', kids_picture_book_note = 'Standing up when it costs something, and how one voice changes a room.', kids_nz_alternative = '', kids_nz_alternative_author = '', kids_nz_alternative_note = '', kids_nz_alternative_verified = false, kids_read_aloud_source_check = '', kids_source = '', kids_game = 'The Hard Right — A simple relay with a shortcut clearly available. Nobody is watching that lane. Afterwards, hands up honestly — who took it? No consequences, just the conversation. WHY IT FITS: Doing the right thing when nobody would know.', kids_game_equipment = 'Cones, floor tape', kids_game_under5 = 'Under-5s run the course with an adult. Skip the shortcut and the discussion; just run and cheer.', kids_colouring_prompt = '' WHERE week_number = 43;
UPDATE public.curriculum_weeks SET kids_picture_book = 'The Sandwich Swap', kids_picture_book_author = 'Queen Rania Al Abdullah & Kelly DiPucchio', kids_picture_book_question = 'What argument do you need to sort out?', kids_picture_book_note = 'Two best friends fall out over lunch, and staying in it makes them closer.', kids_nz_alternative = '', kids_nz_alternative_author = '', kids_nz_alternative_note = '', kids_nz_alternative_verified = false, kids_read_aloud_source_check = '', kids_source = '', kids_game = 'Knot Untie — A group holds hands in a tangle and has to untangle without letting go. Requires talking, patience and not walking off. Facilitator names the moment someone nearly gives up. WHY IT FITS: Staying in the tangle is how it gets sorted.', kids_game_equipment = 'None', kids_game_under5 = 'Under-5s do a three-person tangle with an adult. Fifteen seconds, then untangle and cheer. Hand-holding only with peers or a rostered adult.', kids_colouring_prompt = '' WHERE week_number = 44;
UPDATE public.curriculum_weeks SET kids_picture_book = 'Last Stop on Market Street', kids_picture_book_author = 'Matt de la Peña', kids_picture_book_question = 'What can you give that doesn''t cost anything?', kids_picture_book_note = 'CJ''s nana gives without it costing her — and shows him how to see.', kids_nz_alternative = '', kids_nz_alternative_author = '', kids_nz_alternative_note = '', kids_nz_alternative_verified = false, kids_read_aloud_source_check = '', kids_source = '', kids_game = 'Give-Away Relay — Each child starts with five beanbags and must finish with none — but they can only give them away, never drop them. Some children end up with piles. Then everyone gives again. WHY IT FITS: Giving is more fun than holding.', kids_game_equipment = 'Beanbags', kids_game_under5 = 'Under-5s give one beanbag to someone and get a thank you. That''s the whole game.', kids_colouring_prompt = '' WHERE week_number = 45;
UPDATE public.curriculum_weeks SET kids_picture_book = 'Those Shoes', kids_picture_book_author = 'Maribeth Boelts', kids_picture_book_question = 'What''s already good that you''d stopped noticing?', kids_picture_book_note = 'Jeremy wants the shoes badly, and works out what he already has.', kids_nz_alternative = '', kids_nz_alternative_author = '', kids_nz_alternative_note = '', kids_nz_alternative_verified = false, kids_read_aloud_source_check = '', kids_source = '', kids_game = 'Full Cup — Each child fills a cup with water to where ''enough'' feels right. Then they try to carry it across the hall. The over-fillers spill. Then they try again with less. WHY IT FITS: Enough is easier to carry than more.', kids_game_equipment = 'Cups, water, towels, mats', kids_game_under5 = 'Under-5s use rice or beads instead of water. Same lesson, no mopping.', kids_colouring_prompt = '' WHERE week_number = 46;
UPDATE public.curriculum_weeks SET kids_picture_book = 'The Curious Garden', kids_picture_book_author = 'Peter Brown', kids_picture_book_question = 'What are you practising that''s still hard?', kids_picture_book_note = 'Liam tends something that takes years to show. Roots before shoots.', kids_nz_alternative = 'First to the Top: Sir Edmund Hillary''s Amazing Everest Adventure', kids_nz_alternative_author = 'David Hill, ill. Phoebe Morris', kids_nz_alternative_note = 'Years of unseen preparation before the summit.', kids_nz_alternative_verified = false, kids_read_aloud_source_check = '', kids_source = '', kids_game = 'Sprouting Seeds — Beans planted in cotton wool at week 47, checked every week to week 52. The game is a relay to plant and water them. Nothing visible happens for days. WHY IT FITS: Roots come before the shoot.', kids_game_equipment = 'Beans, cotton wool, cups, water', kids_game_under5 = 'Under-5s do the planting and the watering, which is the good part. Give them their own labelled cup.', kids_colouring_prompt = '' WHERE week_number = 47;
UPDATE public.curriculum_weeks SET kids_picture_book = 'Each Kindness', kids_picture_book_author = 'Jacqueline Woodson', kids_picture_book_question = 'Who made you feel good this week, and how?', kids_picture_book_note = 'Chloe doesn''t take the chance, and it stays with her. Small moments ripple.', kids_nz_alternative = '', kids_nz_alternative_author = '', kids_nz_alternative_note = '', kids_nz_alternative_verified = false, kids_read_aloud_source_check = '', kids_source = '', kids_game = 'Ripple Tag — A calm tag where being tagged means receiving a compliment, not being out. The tagged child then goes and compliments two others. Watch how fast the whole hall is tagged. WHY IT FITS: Small good moments spread further than you think.', kids_game_equipment = 'None', kids_game_under5 = 'Under-5s are tagged first so they get to do the spreading. Keep the compliments simple: ''you''re fun''.', kids_colouring_prompt = '' WHERE week_number = 48;
UPDATE public.curriculum_weeks SET kids_picture_book = 'Miss Rumphius', kids_picture_book_author = 'Barbara Cooney', kids_picture_book_question = 'What do you want people to remember about you?', kids_picture_book_note = 'Make the world more beautiful. The lupins outlast her.', kids_nz_alternative = 'Hero of the Sea: Sir Peter Blake''s Mighty Ocean Quests', kids_nz_alternative_author = 'David Hill, ill. Phoebe Morris', kids_nz_alternative_note = 'A life whose effect carried on past it.', kids_nz_alternative_verified = false, kids_read_aloud_source_check = '', kids_source = '', kids_game = 'Sand Handprints — Each child presses a handprint into a shared tray of sand or dough, then adds one word for what they want to leave behind. The tray goes on the wall. WHY IT FITS: You leave a mark on people.', kids_game_equipment = 'Air-dry clay or a sand tray, board', kids_game_under5 = 'Under-5s do the handprint and say their word out loud for an adult to write. Supervise dough closely.', kids_colouring_prompt = '' WHERE week_number = 49;
UPDATE public.curriculum_weeks SET kids_picture_book = 'Thankful', kids_picture_book_author = 'Eileen Spinelli', kids_picture_book_question = 'What three good things happened today?', kids_picture_book_note = 'Noticing specific, ordinary good things on purpose.', kids_nz_alternative = '', kids_nz_alternative_author = '', kids_nz_alternative_note = '', kids_nz_alternative_verified = false, kids_read_aloud_source_check = '', kids_source = '', kids_game = 'Ten Good Things Scavenger Hunt — Teams find ten specific good things in the hall or in each other — someone''s laugh, a good pass, a kind word, a warm coat. Not objects. Noticings. WHY IT FITS: The more you look, the more you find.', kids_game_equipment = 'Checklist cards, pencils', kids_game_under5 = 'Under-5s find three things with a buddy, using pictures rather than words on the card.', kids_colouring_prompt = '' WHERE week_number = 50;
UPDATE public.curriculum_weeks SET kids_picture_book = 'Everyone Can Learn to Ride a Bicycle', kids_picture_book_author = 'Chris Raschka', kids_picture_book_question = 'What will you keep practising?', kids_picture_book_note = 'Falling off and getting back on, again and again. There is no finish line.', kids_nz_alternative = '', kids_nz_alternative_author = '', kids_nz_alternative_note = '', kids_nz_alternative_verified = false, kids_read_aloud_source_check = '', kids_source = '', kids_game = 'The Never-Finished Tower — Build a tower. When it gets tall, add one more block. Then one more. It falls, and you start again. The game has no end and no winner. Play until time runs out. WHY IT FITS: There''s no finish line. That''s the good bit.', kids_game_equipment = 'Blocks', kids_game_under5 = 'Under-5s knock it down and rebuild endlessly, which is exactly the point. Do not stop them.', kids_colouring_prompt = '' WHERE week_number = 51;
UPDATE public.curriculum_weeks SET kids_picture_book = 'Oh, the Places You''ll Go!', kids_picture_book_author = 'Dr. Seuss', kids_picture_book_question = 'What can you do now that you couldn''t a year ago?', kids_picture_book_note = 'A whole year, and the road carrying on past it.', kids_nz_alternative = '', kids_nz_alternative_author = '', kids_nz_alternative_note = '', kids_nz_alternative_verified = false, kids_read_aloud_source_check = '', kids_source = '', kids_game = 'The Whole Year Trail — Fifty-two stations is too many — pick thirteen, one per month-ish, each with an object from that session. Children walk the trail and say one thing at any station they choose. Ends with the whole room in a circle. WHY IT FITS: Looking back at all of it.', kids_game_equipment = 'Objects from the year, station cards', kids_game_under5 = 'Under-5s walk the trail with an adult and pick up the objects. Six stations. Let them carry something home.', kids_colouring_prompt = '' WHERE week_number = 52;
